#include "quota.h"

// Empaquetado RGB565 estandar: value = (r5<<11)|(g6<<5)|b5.
// El ESP8266 es little-endian, asi que antes de tft.pushImage()
// hay que llamar a tft.setSwapBytes(true) para que TFT_eSPI
// intercambie los bytes al orden que espera el bus SPI del panel.
// El fondo (fuera de la mascota) es la clave de transparencia 0x0000.
// ponytail: los arrays son `const` a nivel de fichero -> linkage interno,
// asi que cada .cpp que incluya este header se lleva su propia copia
// (~180 KB) de las 12 tablas. Vale para el TU unico de hoy (sprites.cpp);
// si T12 necesita usarlas desde otro .cpp, declarar `extern` aqui y mover
// las definiciones a sprites.cpp para no duplicar flash.

